(() => {
  const {$,esc,colors,types,image,favoriteIds}=Atlas;
  const all=window.ATLAS_CATALOG?.cards||[];
  const key=new URLSearchParams(location.search).get('id');
  const c=all.find(card=>card.uid===key)||all.find(card=>card.id===key);
  if(!c){
    $('#card-page').innerHTML='<div class="catalog-empty"><span>✧</span><h1>Carta não encontrada.</h1><p>Confira o ID ou escolha outra carta na biblioteca.</p><a class="btn-gold" href="home.html">Voltar à biblioteca ↗</a></div>';
    return;
  }
  const info=AtlasDescriptions.describe(c);
  const variants=all.filter(card=>card.id===c.id);
  document.title=c.name+' · '+c.id+' — Grand Line Atlas';
  const stats=c.type==='DON'?[['Categoria','Recurso'],['Quantidade no deck','10'],['Bônus normal','+1000'],['Duração','Seu turno'],['Cor','Sem cor'],['Registro',c.id]]:[[c.type==='LEADER'?'Vida inicial':'Custo em DON!!',c.type==='LEADER'?c.life:c.cost],['Poder base',c.power],['Counter',c.counter],['Atributo',c.attribute],['Raridade',info.rarity],['Bloco',c.block]];
  const sourceName=c.sourceKind==='oplay'?'OPlayTCG':'Bandai';const actionType=c.type==='LEADER'?'leader':c.type==='DON'?'don':'add';
  const favoriteButton=()=>`<button class="btn-gold" data-favorite="${esc(c.id)}" aria-pressed="${favoriteIds().includes(c.id)}">${favoriteIds().includes(c.id)?'♥ Salva nos favoritos':'♡ Guardar este tesouro'}</button>`;
  const marked=value=>esc(value).replace(/\[([^\]]+)\]/g,'<mark>[$1]</mark>');
  const colored=c.color?c.color.split('/').map(value=>`<span><i style="background:${colors[value]?.[1]||'#aaa'}"></i>${colors[value]?.[0]||esc(value)}</span>`).join(''):'<span>Sem cor · recurso</span>';
  $('#card-page').innerHTML=`
    <div class="breadcrumbs"><a href="home.html">Biblioteca</a><span>/</span><span>${esc(c.id)}</span><span class="edition-count">${variants.length} ${variants.length===1?'arte no Atlas':'artes no Atlas'}</span></div>
    <div class="full-card-layout">
      <div class="full-card-visual wanted-frame" style="--card-accent:${colors[c.color.split('/')[0]]?.[1]||'#e9bc65'}">
        <div class="wanted-heading"><span>✦</span> WANTED <span>✦</span></div><span class="wanted-subtitle">A NEW TREASURE FOR YOUR COLLECTION</span>
        <div class="full-card-glow"></div><div class="card-stage"><button class="zoom-card" id="open-art" aria-label="Ampliar a carta ${esc(c.name)}"><img src="${esc(image(c))}" data-original="${esc(c.image)}" alt="${esc(c.name)} — ${esc(c.uid)}" id="detail-image" width="400" height="560"><span class="foil-sheen" aria-hidden="true"></span><span class="zoom-hint">⌕ AMPLIAR ILUSTRAÇÃO</span></button></div>
        <span class="wanted-card-name">${esc(c.name)}</span><div class="wanted-edition"><span>${esc(c.uid)}</span><b>${esc(c.rarity)}</b></div><small class="poster-caption">PÔSTER DE COLEÇÃO · IMAGEM DO CATÁLOGO · ${esc(sourceName)}</small>
      </div>
      <div class="full-card-copy"><div class="eyebrow gold">${esc(c.id)} <span class="type-pill">${types[c.type]}</span></div><h1>${esc(c.name)}</h1><div class="card-color-labels">${colored}</div><p class="character-types">${esc(c.archetype)}</p><div class="card-topic-links">${AtlasTaxonomy.tags(c).map(id=>`<a href="home.html?tags=${id}">${esc(AtlasTaxonomy.topics.find(t=>t.id===id).label)}</a>`).join('')}</div>
        <div class="card-intro"><h2>${esc(info.focus)}</h2><p>${esc(info.intro)}</p></div>
        <div class="full-card-stats">${stats.map(([label,value])=>`<div><small>${label}</small><b>${esc(value??'—')}</b></div>`).join('')}</div><div id="detail-favorite">${favoriteButton()}</div><div class="card-utility-links"><a href="decks.html?${actionType}=${encodeURIComponent(c.uid)}">⚑ ${c.type==='LEADER'?'Usar como Líder':c.type==='DON'?'Usar esta arte de DON!!':'Adicionar ao meu deck'}</a><a href="comprar.html?id=${encodeURIComponent(c.uid)}">Onde conseguir ↗</a></div>${c.spoiler?'<p class="preview-notice">Prévia: este registro pode mudar e não confirma disponibilidade ou legalidade em evento.</p>':''}${c.imageStatus==='placeholder'?'<p class="source-label">A fonte identifica esta ilustração como provisória.</p>':''}
        <div class="card-reading"><span class="panel-label">LEITURA EM PORTUGUÊS</span><p>${esc(info.reading)}</p>${info.curated?`<div class="reading-attention"><span>✧</span><p>${esc(info.curated.watch)}</p></div>`:''}<span class="description-provenance">${info.curated?'Explicação editorial com base no registro importado.':'Resumo dos campos publicados no catálogo.'} Confira o efeito oficial e suas condições abaixo.</span></div>
      </div>
    </div>
    <div class="reading-grid">
      <section class="info-panel field-guide"><div class="eyebrow gold">COMO LER ESTA CARTA</div><h2>O que observar na partida.</h2>${info.hints.length?`<ul>${info.hints.map(h=>`<li>${esc(h)}</li>`).join('')}</ul>`:'<p>Observe o custo, as condições, os alvos e a duração de cada parte do efeito. Não atribua habilidades a esta carta apenas por sua cor ou personagem.</p>'}${info.timings.length?`<div class="timing-list">${info.timings.map(t=>`<div><span class="timing-dot"></span><div><b>${esc(t.label)}</b><small>${esc(t.key)}</small><p>${esc(t.explanation)}</p></div></div>`).join('')}</div>`:''}<a class="small-guide-link" href="aprender.html#anatomia">Revisar os campos de uma carta ↗</a></section>
      <section class="info-panel effect-panel"><div class="eyebrow gold">TEXTO DA FONTE · INGLÊS</div><h2>O efeito, sem perder detalhes.</h2><p lang="en">${marked(c.effect||'Este registro não apresenta efeito impresso.')}</p>${c.trigger?`<div class="trigger-panel"><b>TRIGGER · EFEITO SEPARADO</b><p lang="en">${marked(c.trigger)}</p></div>`:''}<a href="${esc(c.source)}" target="_blank" rel="noopener">Conferir o registro na fonte ${esc(sourceName)} ↗</a></section>
    </div>
    ${info.keywords.length?`<section class="ability-explainer"><div class="eyebrow gold">DECIFRANDO O TEXTO</div><div class="ability-heading"><h2>As habilidades mencionadas.</h2><a href="aprender.html#habilidades">Abrir o glossário ↗</a></div><div class="ability-grid">${info.keywords.map(k=>`<article><span>✧</span><h3>${esc(k.title)}</h3><p>${esc(k.text)}</p><small>Leia no efeito quem possui ou recebe a habilidade.</small></article>`).join('')}</div></section>`:''}
    <div class="card-info-columns"><section class="info-panel"><div class="eyebrow gold">ONDE ENCONTRAR</div><h2>Produtos e coleções.</h2><p>Produtos ou grupos associados a esta impressão na fonte indicada. Reimpressões podem estar em outros registros. O produto não garante uma carta específica em cada pacote.</p><ul class="set-list">${c.sets.map(s=>`<li><a href="home.html?set=${encodeURIComponent(s.id)}&prints=1">${esc(s.name)} <span>↗</span></a></li>`).join('')}</ul><div class="characteristic-tags">${info.characteristics.map(t=>`<a href="home.html?archetype=${encodeURIComponent(t)}">${esc(t)} ↗</a>`).join('')}</div></section><section class="info-panel lore-panel"><div class="eyebrow gold">ALÉM DA CARTA</div><h2>Uma arte. Outra história.</h2><div class="research-status">◷ Origem da ilustração em pesquisa</div><p>A conexão desta arte com uma cena, capa ou desenho original ainda precisa de fonte. O personagem e as características do jogo não bastam para identificar um capítulo.</p><dl class="story-fields"><div><dt>Capítulo e episódio</dt><dd>A verificar por ilustração</dd></div><div><dt>Referência narrativa</dt><dd>Em pesquisa</dd></div></dl></section></div>
    <section class="variants-section"><div class="section-heading"><div><div class="eyebrow gold">O MESMO ID, OUTROS TESOUROS</div><h2>Explore as outras artes.</h2><p>${variants.length} ${variants.length===1?'versão registrada':'versões registradas'} de ${esc(c.id)}. Selecione uma impressão para conhecer seus detalhes.</p></div></div><div class="variant-grid">${variants.map(v=>`<a href="carta.html?id=${encodeURIComponent(v.uid)}" class="variant-link ${v.uid===c.uid?'current':''}" ${v.uid===c.uid?'aria-current="page"':''}><img src="${esc(image(v))}" data-original="${esc(v.image)}" alt="${esc(v.uid)}" width="400" height="560" loading="lazy"><span>${esc(v.uid)}</span></a>`).join('')}</div><p class="data-note">A explicação em português é um apoio de leitura, não uma tradução integral certificada. Valores ausentes na fonte não são inferidos. Consulte formato, texto atual, restrições e erratas antes de um evento.</p></section>
    <dialog id="art-dialog" class="art-dialog" aria-labelledby="art-dialog-title"><button class="dialog-close" aria-label="Fechar ilustração">×</button><div class="art-dialog-header"><span class="eyebrow gold">UM TESOURO EM CADA DETALHE</span><h2 id="art-dialog-title">${esc(c.name)}</h2><span>${esc(c.uid)}</span></div><img src="${esc(image(c))}" data-original="${esc(c.image)}" alt="${esc(c.name)} em tamanho ampliado"><a href="${esc(c.image)}" target="_blank" rel="noopener">Abrir imagem original na fonte ↗</a></dialog>`;
  const art=$('#art-dialog');$('#open-art').onclick=()=>art.showModal();art.querySelector('.dialog-close').onclick=()=>art.close();
  art.addEventListener('click',event=>{if(event.target!==art)return;const rect=art.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)art.close();});
  $('#detail-image').onerror=()=>{const img=$('#detail-image');if(img.dataset.retried&&img.getAttribute('src')!==c.image)return;const status=$('.poster-caption');status.textContent='Ilustração indisponível; consulte o arquivo original.';};
  document.addEventListener('atlas:favorites',()=>$('#detail-favorite').innerHTML=favoriteButton());
})();
